import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# A simple custom CUDA kernel for element-wise ReLU
custom_relu_kernel = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor custom_relu_cuda(torch::Tensor input) {
    auto output = torch::zeros_like(input);
    int size = input.numel();

    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;

    relu_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size
    );
    return output;
}
"""

custom_relu_cpp = "torch::Tensor custom_relu_cuda(torch::Tensor input);"

relu_extension = load_inline(
    name="custom_relu_extension",
    cpp_sources=custom_relu_cpp,
    cuda_sources=custom_relu_kernel,
    functions=["custom_relu_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Performs a transposed 2D convolution with a custom ReLU kernel afterward.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (int): Size of the square convolution kernel.
        stride (int, optional): Stride of the convolution. Defaults to 1.
        padding (int, optional): Padding applied to the input. Defaults to 0.
        output_padding (int, optional): Additional size added to one side of the output shape. Defaults to 0.
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = self.conv_transpose2d(x)
        out = relu_extension.custom_relu_cuda(out)
        return out

def get_inputs():
    batch_size = 16
    in_channels = 32
    height_in = 128
    width_in = 256
    x = torch.randn(batch_size, in_channels, height_in, width_in).cuda()
    return [x]

def get_init_inputs():
    in_channels = 32
    out_channels = 64
    kernel_size = 3
    return [in_channels, out_channels, kernel_size]
